/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field StatementId.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableStatementId extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, StatementId);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::String);

    while select StatementId from retailSalesTable
        group by StatementId
    {
        ret.add(retailSalesTable.StatementId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, StatementId));
    qbr.value(queryValue(_value));
}
